import { computed, reactive } from 'vue'

const draft = reactive({ query: '', cents: 0 })
const products = reactive<{ id: string; name: string; cents: number }[]>([])

const visible = computed(() => {
  const q = draft.query.trim().toLowerCase()
  return products.filter((item) => item.name.toLowerCase().includes(q))
})

const dollars = computed({
  get: () => (draft.cents / 100).toFixed(2),
  set: (input: string) => {
    const next = Number(input)
    if (Number.isFinite(next)) draft.cents = Math.round(next * 100)
  },
})

import { ref, watch } from 'vue'

const query = ref('')
const results = ref<string[]>([])

watch(query, async (value, _prev, onCleanup) => {
  const controller = new AbortController()
  onCleanup(() => controller.abort())
  const response = await fetch(`/api/search?q=${encodeURIComponent(value)}`, {
    signal: controller.signal,
  })
  if (controller.signal.aborted) return
  results.value = await response.json()
})

