import { inject, provide, reactive, type InjectionKey } from 'vue'

interface FormContext {
  disabled: boolean
  register(id: string): void
}

const formKey: InjectionKey<FormContext> = Symbol('form')

export function provideForm() {
  const form = reactive<FormContext>({
    disabled: false,
    register(id) { /* track fields */ void id },
  })
  provide(formKey, form)
  return form
}

export function useFormContext() {
  const form = inject(formKey)
  if (!form) throw new Error('useFormContext() requires provideForm()')
  return form
}
